static void make_input(uint8_t* out, size_t* out_len)
{
    /* Randomly choose flags: 50% ADMONITIONS-related combos, else random. */
    static const uint32_t flag_sets[] = {
        0x80000,            /* ADMONITIONS */
        0x80001,            /* ADMONITIONS | COLLAPSEWHITESPACE */
        0x80000 | 0x100,    /* + TABLES */
        0x80000 | 0x200,    /* + STRIKETHROUGH */
        0x80000 | 0x10000,  /* + SPOILERS */
        0x80000 | 0x20000,  /* + SUPERSCRIPTS */
        0x80000 | 0x40000,  /* + SUBSCRIPTS */
        0x80000 | 0x800,    /* + TASKLISTS */
        0x80000 | 0x2000,   /* + WIKILINKS */
        0x80000 | 0x1000,   /* + LATEXMATHSPANS */
        0x80000 | 0x4000,   /* + UNDERLINE */
        0xffffffff,
        0x0,
        0x16d,
        0x100,
        0x200,
        0x10000,
        0x20000,
        0x40000,
        0xffff,
        0x80000 | 0x16d,
    };
    uint32_t pf = flag_sets[rnd() % (sizeof(flag_sets)/sizeof(flag_sets[0]))];
    uint32_t rf = (rnd() & 1) ? (1u << (rnd() % 4)) : 0;
    uint32_t* hdr = (uint32_t*) out;
    hdr[0] = pf;
    hdr[1] = rf;

    size_t pos = 8;
    /* Start from a seed corpus entry with some probability. */
    if((rnd() % 100) < 60) {
        const char* s = seeds[rnd() % (sizeof(seeds)/sizeof(seeds[0]))];
        size_t len = strlen(s);
        memcpy(out + pos, s, len);
        pos += len;
    }

    /* Apply 1-8 mutations. */
    int nmut = 1 + rnd() % 8;
    for(int m = 0; m < nmut; m++) {
        switch(rnd() % 6) {
            case 0: { /* flip a byte */
                if(pos <= 8) break;
                out[8 + rnd() % (pos - 8)] ^= (1u << (rnd() % 8));
                break;
            }
            case 1: { /* insert random byte */
                if(pos >= MAX_INPUT - 1) break;
                size_t at = 8 + rnd() % (pos - 7);
                memmove(out + at + 1, out + at, pos - at);
                out[at] = (uint8_t) rnd();
                pos++;
                break;
            }
            case 2: { /* delete chunk */
                if(pos <= 8) break;
                size_t at = 8 + rnd() % (pos - 8);
                size_t n = 1 + rnd() % ((pos - at) < 16 ? (pos - at) : 16);
                memmove(out + at, out + at + n, pos - at - n);
                pos -= n;
                break;
            }
            case 3: { /* insert dictionary token */
                const char* t = dict[rnd() % (sizeof(dict)/sizeof(dict[0]))];
                size_t tl = strlen(t);
                if(pos + tl >= MAX_INPUT) break;
                size_t at = 8 + rnd() % (pos - 7);
                memmove(out + at + tl, out + at, pos - at);
                memcpy(out + at, t, tl);
                pos += tl;
                break;
            }
            case 4: { /* overwrite a chunk with dictionary token */
                const char* t = dict[rnd() % (sizeof(dict)/sizeof(dict[0]))];
                size_t tl = strlen(t);
                if(pos - 8 < tl) break;
                size_t at = 8 + rnd() % (pos - 8 - tl + 1);
                memcpy(out + at, t, tl);
                break;
            }
            case 5: { /* duplicate a chunk */
                if(pos >= MAX_INPUT - 64) break;
                size_t at = 8 + rnd() % (pos - 8);
                size_t n = 1 + rnd() % ((pos - at) < 32 ? (pos - at) : 32);
                if(pos + n >= MAX_INPUT) break;
                memcpy(out + pos, out + at, n);
                pos += n;
                break;
            }
        }
    }
    if(pos == 8) {
        memcpy(out + 8, "> [!tip]\n> foo\n", 15);
        pos = 23;
    }
    if(pos > MAX_INPUT) pos = MAX_INPUT;
    *out_len = pos;
}

int main(void)
{
    /* mmap a shared file to record the latest input. Layout: [u32 size][bytes]. */
    int fd = open("cur_input.bin", O_RDWR | O_CREAT | O_TRUNC, 0644);
    if(fd < 0) { perror("open"); return 1; }
    if(ftruncate(fd, 1 << 20) != 0) { perror("ftruncate"); return 1; }
    uint8_t* rec = (uint8_t*) mmap(NULL, 1 << 20, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if(rec == MAP_FAILED) { perror("mmap"); return 1; }

    uint8_t buf[MAX_INPUT];
    for(uint64_t iter = 0; ; iter++) {
        size_t len;
        make_input(buf, &len);
        /* Record before running. */
        memcpy(rec, &len, 4);
        memcpy(rec + 4, buf, len);
        if((iter % 100000) == 0)
            fprintf(stderr, "iter=%llu len=%zu\n", (unsigned long long) iter, len);
        LLVMFuzzerTestOneInput(buf, len);
    }
    return 0;
}

